save(258,dict(paragraphs=["Gargi Sarkhel Bagchi is a Pune-based poet and educator with a background in German teaching. Her debut poetry collection, Two Cents For My Thoughts, appeared in 2023. In an essay about her writing, she describes poetry as a way of understanding experience amid the demands of daily life. Her published work pays particular attention to women's voices and the relationships that shape them.","Endangered gives its appeal for a girl's right to live to a speaker still in the womb. Its direct questions and regular rhyming stanzas expose the cruelty of judging a child through a preference for sons. Promises of study, work and care for ageing parents sharpen the argument, while the final stanza places this unheard voice against the wider language of women's rights."],sources=[source('Our Poetry Archive — Gargi Sarkhel Bagchi','https://ourpoetryarchive.blogspot.com/2023/03/gargi-sarkhel-bagchi.html','Matching Endangered poem and contributor biography: Pune, German teaching.'),source('The Perfect Voice — The Poetry of a Woman’s Voice','https://www.theperfectvoice.in/post/the-poetry-of-a-woman-s-voice','Author’s own account of writing and debut collection.'),source('Yugen Quest Review — Two Cents For My Thoughts','https://weliterarydynamic.wordpress.com/book-review-two-cents-for-my-thoughts-by-gargi-sarkhel-bagchi-reviewed-by-smeetha-bhoumik-yqr-aug-2023/','Review identifies debut collection, Authors Press,2023.')],books=[dict(title='Two Cents For My Thoughts',detail='Poetry, Authors Press, 2023; review by Smeetha Bhoumik in Yugen Quest Review.',url='https://weliterarydynamic.wordpress.com/book-review-two-cents-for-my-thoughts-by-gargi-sarkhel-bagchi-reviewed-by-smeetha-bhoumik-yqr-aug-2023/')],identity_match='Exact poem Endangered with same byline plus German teaching, journal affiliations and debut title from archived biography give a secure match.',captured_biography_source='kb/artifacts/content-import/editions/issue-10/poem-246.html; Author section read in full. Writer is archive-discovered, absent from directory profile JSON.',poems_read=[dict(id=246,title='Endangered',coverage='Complete original English poem and complete archived author biography',basis='Unborn female speaker, plea against killing, son-preference, education/economic worth/care and closing women’s rights contrast.')],limitations=['OPA has “become” where captured poem has “accomplish”; preserved local poem unchanged.','2023 Indian Women Rising Star described broadly in captured biography; organiser ALSphere specifies Certificate of Excellence, not category winner. New narrative omits award roll.','No current employment or duration inferred from dated biography.'],research_leads=[dict(url='https://alsphere.org/annual-awards-23/',access='search_index_award_list',finding='Indian Women Rising Star Award: Certificate of Excellence (Literature), Gargi Sarkhel Bagchi; broad winner wording not repeated.')],search_queries=['"Gargi Sarkhel Bagchi" poet','"Gargi Sarkhel Bagchi" "Two Cents" publisher'],next_action='Author/editor factual review, including precise award wording and dated employment note.'))
